import Style from './FriendList.module.css';

import { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import searchFriend from '../../api/search/friend/friendList';

import friendDelete from '../../api/delete/friend';
import { profileImageUrl } from '../../utils/serverOrigin';

export default function FriendList({ friendChange, setFriendChange }) {
    const { userInfo } = useAuth();

    const [friendList, setFriendList] = useState();

    useEffect(() => {
        const request = async () => {
            const data = await searchFriend();
            if (data?.success) {
                setFriendList(data.data);
                return;
            }
            setFriendList([]);
        };
        request();
    }, [userInfo, friendChange]);

    const deleteFriend = async (friend_id) => {
        if (!window.confirm('친구를 삭제하시겠습니까?')) {
            return;
        }
        const request = await friendDelete(friend_id);
        alert(request?.message);
        if (request?.success) {
            setFriendChange((value) => !value);
        }
    };

    return (
        <div className={Style.friendMain}>
            {userInfo ? (
                <div className={Style.friend}>
                    <div className={Style.title}>
                        <h4>친구 목록</h4>
                    </div>
                    {friendList ? (
                        <div className={Style.listWrap}>
                            {friendList.length === 0 ? (
                                <p className={Style.emptyHint}>아직 친구가 없어요.</p>
                            ) : null}
                            {friendList?.map((friendInfo) => (
                                <div className={Style.card} key={friendInfo.friend_id}>
                                    <img
                                        src={profileImageUrl(friendInfo.profile)}
                                        alt=""
                                        className={Style.avatar}
                                    />
                                    <div className={Style.cardBody}>
                                        <h3 className={Style.name}>{friendInfo.username}</h3>
                                        <p className={Style.email}>{friendInfo.email}</p>
                                        <button
                                            type="button"
                                            className={Style.delBtn}
                                            onClick={() => deleteFriend(friendInfo.friend_id)}
                                        >
                                            삭제
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className={Style.title}>
                            <h5>불러오는 중…</h5>
                        </div>
                    )}
                </div>
            ) : null}
        </div>
    );
}
